-- P1 第二阶段：个人效率与知识积累（PostgreSQL 17）

CREATE TABLE IF NOT EXISTS "kb_category" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "owner_id" bigint NOT NULL, "name" varchar(100) NOT NULL, "type" varchar(30) NOT NULL DEFAULT 'KNOWLEDGE',
  "sort" int NOT NULL DEFAULT 0, "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS "kb_category_owner_type_name" ON "kb_category" ("owner_id", "type", "name");
CREATE INDEX IF NOT EXISTS "kb_category_owner_type" ON "kb_category" ("owner_id", "type", "sort");

CREATE TABLE IF NOT EXISTS "kb_tag" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "owner_id" bigint NOT NULL, "name" varchar(60) NOT NULL, "color" varchar(20), "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS "kb_tag_owner_name" ON "kb_tag" ("owner_id", "name");

CREATE TABLE IF NOT EXISTS "kb_article_meta" (
  "article_id" bigint PRIMARY KEY, "category_id" bigint, "owner_id" bigint NOT NULL, "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "kb_article_meta_owner_category" ON "kb_article_meta" ("owner_id", "category_id");
CREATE TABLE IF NOT EXISTS "kb_article_tag" (
  "article_id" bigint NOT NULL, "tag_id" bigint NOT NULL, "owner_id" bigint NOT NULL, PRIMARY KEY ("article_id", "tag_id")
);
CREATE INDEX IF NOT EXISTS "kb_article_tag_owner_tag" ON "kb_article_tag" ("owner_id", "tag_id");
CREATE TABLE IF NOT EXISTS "kb_article_relation" (
  "article_id" bigint NOT NULL, "related_article_id" bigint NOT NULL, "owner_id" bigint NOT NULL, "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("article_id", "related_article_id")
);
CREATE INDEX IF NOT EXISTS "kb_article_relation_related" ON "kb_article_relation" ("related_article_id", "owner_id");

CREATE TABLE IF NOT EXISTS "dev_snippet" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "owner_id" bigint NOT NULL, "category_id" bigint,
  "title" varchar(200) NOT NULL, "language" varchar(30) NOT NULL, "content" text NOT NULL, "description" text, "example" text, "tags" varchar(1000),
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, "deleted" smallint NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS "dev_snippet_owner_language" ON "dev_snippet" ("owner_id", "language", "deleted", "update_time");
CREATE TABLE IF NOT EXISTS "project_document" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "owner_id" bigint NOT NULL, "category_id" bigint,
  "project_name" varchar(100) NOT NULL, "title" varchar(200) NOT NULL, "document_type" varchar(30) NOT NULL, "content" text NOT NULL, "tags" varchar(1000), "status" varchar(20) NOT NULL DEFAULT 'DRAFT',
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, "deleted" smallint NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS "project_document_owner_project" ON "project_document" ("owner_id", "project_name", "deleted", "update_time");
CREATE TABLE IF NOT EXISTS "personal_task" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "owner_id" bigint NOT NULL, "title" varchar(200) NOT NULL, "description" text,
  "status" varchar(20) NOT NULL DEFAULT 'TODO', "priority" varchar(20) NOT NULL DEFAULT 'MEDIUM', "progress" int NOT NULL DEFAULT 0, "plan_date" date, "due_time" timestamp, "recurrence_rule" varchar(200), "completed_time" timestamp,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, "deleted" smallint NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS "personal_task_owner_status_date" ON "personal_task" ("owner_id", "status", "deleted", "plan_date", "due_time");
CREATE TABLE IF NOT EXISTS "kb_transfer_record" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "owner_id" bigint NOT NULL, "direction" varchar(20) NOT NULL, "data_type" varchar(30) NOT NULL, "format" varchar(20) NOT NULL, "status" varchar(20) NOT NULL,
  "total_count" int NOT NULL DEFAULT 0, "success_count" int NOT NULL DEFAULT 0, "failed_count" int NOT NULL DEFAULT 0, "error_message" text, "payload" text,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "kb_transfer_owner" ON "kb_transfer_record" ("owner_id", "status", "create_time");

INSERT INTO "sys_menu" ("parent_id", "name", "path", "component", "type", "permission", "icon", "sort", "status", "create_time", "update_time")
SELECT 0, '开发工作台', '/productivity', 'productivity/index', 1, 'productivity:workspace:list', 'Monitor', 4, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "sys_menu" WHERE "path" = '/productivity');
INSERT INTO "sys_role_menu" ("role_id", "menu_id")
SELECT 1, m."id" FROM "sys_menu" m WHERE m."path" = '/productivity' AND NOT EXISTS (SELECT 1 FROM "sys_role_menu" rm WHERE rm."role_id" = 1 AND rm."menu_id" = m."id");
